// Writes netlify/lib/tool-slugs.mjs (the suggestion function's allowlist of
// tool slugs) from site.config.json. Runs before every `npm run build`.
// CI fails if the committed copy drifts from the config.
import { readFileSync, writeFileSync } from "node:fs";

const cfg = JSON.parse(readFileSync(new URL("../site.config.json", import.meta.url), "utf8"));
const slugs = JSON.stringify(cfg.tools.map((t) => t.slug), null, 2);
writeFileSync(new URL("../netlify/lib/tool-slugs.mjs", import.meta.url),
  "// GENERATED by scripts/gen-tool-slugs.mjs from site.config.json — do not edit.\n" +
  "// The suggestion function accepts only these tool slugs.\n" +
  `export default ${slugs};\n`);

